WFJ.Data.add("book", {
  ["cd35e5f729c071cb"] = { "Il grande ammiraglio costrinse Jaina a una scelta terribile: sostenerlo nella battaglia contro gli orchi e tradire i suoi nuovi alleati, oppure combattere il proprio padre per preservare la fragile pace che l'⟦Alliance=Alleanza⟧ e l'⟦Horde=Orda⟧ avevano finalmente raggiunto. Dopo un lungo travaglio interiore, Jaina scelse la seconda strada e aiutò Thrall a sconfiggere il padre impazzito.", "." },
  ["cd3aa376de518d4d"] = { "I magocrati proposero di conferire potere a un unico campione mortale, che avrebbe usato i loro poteri per combattere una guerra segreta senza fine contro la Legione. Si insistette sul fatto che la maggior parte dell'umanità non avrebbe mai dovuto sapere dei Guardiani né della minaccia della Legione, per timore che si ribellasse in preda alla paura e alla paranoia. Gli elfi accettarono la proposta e fondarono una società segreta che avrebbe vigilato sulla scelta del Guardiano e contribuito ad arginare l'avanzata del caos nel mondo.", "." },
  ["cd68ae3c38289787"] = { "quel periodo su cui dovrei richiamare l'attenzione di Vostra Maestà. Innanzitutto, fu allora che mi venne offerta la carica di architetto cittadino, a patto che non mi unissi a VanCleef. Per certe divergenze ideologiche, scelsi di restare a ⟦Stormwind=Roccavento⟧. Durante le rivolte, il luogotenente e assistente più fidato di VanCleef, Bazil Thredd, fu catturato e imprigionato. In attesa di processo e di interrogatorio, Thredd fu quasi dimenticato nelle ⟦Stockade=Segrete di Roccavento⟧. Tornando a VanCleef, dopo che ebbe condotto i resti dei", "." },
  ["cdc71f2ff7512320"] = { "Tichondrius, il più potente e astuto dei signori del terrore, accolse la sfida con entusiasmo: era affascinato dalla violenza della piaga e dallo sfrenato potenziale di sterminio del Re dei Lich.", "." },
  ["cdf92dadf3addff2"] = { "Va qui sottolineato che il latore di questo rapporto è stato determinante non solo per il successo della nostra missione, ma anche per la sconfitta di Ivar il Lurido, il salvataggio di Erland e la consegna di questo rapporto.\n\nEsprimiamo la nostra gratitudine e raccomandiamo che il comando conferisca a questa persona onorificenze adeguate alla condotta meritoria dimostrata sul campo.\n\n-Inseguitore della Morte Rane Yorick,\n\nCapo della missione", "." },
})
